<!--
 * @Description: videoJs播放视频组件 页面
 * @Author: mhf
 * @Date: 2024-06-04 13:25:33
 * @params: 注意：如果遇报错等信息，请让硬件厂商将视频文件转换为H.264编码格式。
-->
<template>
  <div class="real_player">
    <vue-video-player
      class="video-player-box"
      ref="videoPlayer"
      :options="playerOptions"
      :playsinline="true"
      :style="videoStyle"
      customEventName="customstatechangedeventname"
      @play="onPlayerPlay"
      @pause="onPlayerPause"
      @ended="onPlayerEnded"
      @waiting="onPlayerWaiting"
      @playing="onPlayerPlaying"
      @loadeddata="onPlayerLoadeddata"
      @timeupdate="onPlayerTimeupdate"
      @canplay="onPlayerCanplay"
      @canplaythrough="onPlayerCanplaythrough"
      @statechanged="playerStateChanged"
      @ready="playerReadied"
    >
    </vue-video-player>
    <div class="box_shadow">
      <div class="capture" @click="handleClick('pic')">
        <i class="iconfont icon-jietu" style="font-size: 22px; color: #fff"></i>
      </div>
      <div class="fullscreen" @click="handleClick('screen')">
        <i
          class="iconfont icon-quanping"
          style="font-size: 20px; color: #fff"
        ></i>
      </div>
      <div class="control" @click="handleClick('control')">
        <i
          v-if="isControl"
          class="iconfont icon-fanhui"
          style="font-size: 22px; color: #fff"
        ></i>
        <i
          v-else
          class="iconfont icon-kongzhi"
          style="font-size: 22px; color: #fff"
        ></i>
      </div>
    </div>
  </div>
</template>
<!--
        // 视频格式
        type："video/webm"   // 可以播放，用ogg也可打开
        type："video/ogg"    // 可以播放，用webm也可打开
        type："video/3gp"    // 可以播放
        type："video/mp4"    // 可以播放
        // 组件方法
        重置进度条
        this.player.src(src)
        加载视频
        this.player.load();
        播放视频
        this.player.play();
        暂停播放
        this.player.pause();
        直接全屏 如果当前设备支持的话
        this.player.requestFullscreen();
        在全屏模式下，将视频恢复到正常大小
        this.player.exitFullscreen();
        当环境不支持全屏时 则扩展铺满容器
        this.player.enterFullWindow();
        重置播放器
        this.player.reset();
        返回当前播放源信息
        this.player.currentSources();
        获取或者设置预加载属性
        this.player.preload(val);
        播放控件是否显示
        this.player.controls(false);
        /* 父组件可以通过获取当前组件的 player 来调用 videoPlayer 组件的方法 */
     -->
<script>
import { videoPlayer } from "vue-video-player";
import "video.js/dist/video-js.css";
import "vue-video-player/src/custom-theme.css";
import "videojs-contrib-hls";

export default {
  name: "videoItem",
  components: {
    VueVideoPlayer: videoPlayer,
  },
  props: {
    sourceSrc: {
      type: String,
      default: "",
    },
    isControl: {
      type: Boolean,
      default: false,
    },
    obj: {
      type: Object,
      default: () => {
        return {}; //设备基本信息，通过 assetCode 进行控制
      },
    },
    autoPlay: {
      type: Boolean,
      default: true,
    },
    videoStyle: {
      type: Object,
      default: () => {
        return {
          "--videoHeight": "396px",
        };
      },
    },
  },
  watch: {
    sourceSrc: {
      handler(val) {
        if (val) {
          this.playerOptions.sources = [
            {
              type: "application/x-mpegURL",
              src: val,
            },
          ];
          // this.playerOptions.sources.push();
        }
      },
      immediate: true,
    },
    isFullscreen: {
      handler(val) {
        if (!val) {
          console.log("变化");
          this.player.controls(false);
        }
      },
    },
  },
  data() {
    return {
      isFullscreen: false,
      playerOptions: {
        // videojs options
        // 是否等浏览器准备好后自动播放
        autoplay: this.autoPlay,
        // 是否静音
        muted: true,
        // 结束后是否重新开始
        loop: false,
        // 语言
        language: "en",
        // 播放速度可选列表
        playbackRates: [],
        // 播放视频源
        sources: [
          {
            type: "application/x-mpegURL",
            src: "http://219.151.31.38/liveplay-kk.rtxapp.com/live/program/live/hnwshd/4000000/mnf.m3u8",
          },
        ],
        // 视频比例
        // aspectRatio: '4:3',
        fluid: true,
        // 封面
        // poster: '/static/images/author.jpg'
        controlBar: {
          //当前时间和持续时间的分隔符
          timeDivider: true,
          //显示持续时间
          durationDisplay: false,
          //是否显示剩余时间功能
          remainingTimeDisplay: false,
          //全屏按钮
          fullscreenToggle: true,
          //播放暂停按钮
          playToggle: true,
          //音量控制
          volumeMenuButton: false,
          //当前播放时间
          currentTimeDisplay: false,
          //点播流时，播放进度条，seek控制
          progressControl: true,
          //直播流时，显示LIVE
          liveDisplay: true,
          //播放速率，当前只有html5模式下才支持设置播放速率
          playbackRateMenuButton: false,
        },
      },
    };
  },
  mounted() {
    // 监听全屏状态变化
    document.addEventListener("fullscreenchange", this.handleFullscreenChange);
    document.addEventListener(
      "webkitfullscreenchange",
      this.handleFullscreenChange
    );
    document.addEventListener(
      "mozfullscreenchange",
      this.handleFullscreenChange
    );
    document.addEventListener(
      "MSFullscreenChange",
      this.handleFullscreenChange
    );
    this.player.controls(false);
  },
  beforeDestroy() {
    // 在组件销毁前移除监听事件
    document.removeEventListener(
      "fullscreenchange",
      this.handleFullscreenChange
    );
    document.removeEventListener(
      "webkitfullscreenchange",
      this.handleFullscreenChange
    );
    document.removeEventListener(
      "mozfullscreenchange",
      this.handleFullscreenChange
    );
    document.removeEventListener(
      "MSFullscreenChange",
      this.handleFullscreenChange
    );
  },
  computed: {
    player() {
      return this.$refs.videoPlayer.player;
    },
  },
  methods: {
    handleFullscreenChange() {
      this.isFullscreen =
        document.fullscreenElement ||
        document.webkitFullscreenElement ||
        document.mozFullScreenElement ||
        document.msFullscreenElement
          ? true
          : false;
    },
    // 下载截图
    downLoadPic() {
      // const blob = new Blob([res.data], { type: "image/png" });
      //     this.codeUrl = window.URL.createObjectURL(blob);
      const image = new Image();
      // 解决跨域 Canvas 污染问题
      image.setAttribute("crossOrigin", "anonymous");
      image.onload = function () {
        const canvas = document.createElement("canvas");
        canvas.width = image.width;
        canvas.height = image.height;
        const context = canvas.getContext("2d");
        context.drawImage(image, 0, 0, image.width, image.height);
        const url = canvas.toDataURL("image/png"); // 得到图片的base64编码数据
        const a = document.createElement("a"); // 生成一个a元素
        const event = new MouseEvent("click"); // 创建一个单击事件
        a.download = `${this.rowData.deviceName}二维码`; // 设置图片名称
        a.href = url; // 将生成的URL设置为a.href属性
        a.dispatchEvent(event); // 触发a的单击事件
      };
      image.src = this.codeUrl;
    },
    getVideoPicture() {
      let video = document.getElementsByClassName("vjs-tech")[0];
      let canvas = document.createElement("canvas");
      let w = window.innerWidth;
      let h = (window.innerWidth / 16) * 9;
      canvas.width = w;
      canvas.height = h;
      const ctx = canvas.getContext("2d");
      ctx.drawImage(video, 0, 0, w, h);
      ctx.drawImage(video, 0, 0, w, h);
      let previewImg = canvas.toDataURL("image/png");
      let a = document.createElement("a");
      const event = new MouseEvent("click"); // 创建一个单击事件
      a.download = "截图"; // 设置图片名称
      a.href = previewImg; // 将生成的URL设置为a.href属性
      a.dispatchEvent(event); // 触发a的单击事件
    },
    handleClick(type) {
      switch (type) {
        case "pic":
          this.getVideoPicture();
          break;
        case "screen":
          this.player.controls(true);
          this.player.requestFullscreen();
          break;
        case "control":
          this.$emit("on-control");
          break;
        default:
          break;
      }
    },
    // 播放(播放时会调用)(用户操作调用)
    onPlayerPlay(player) {
      // console.log("播放", player);
      // this.player.pause();
      this.$emit("onPlayerPlay", player);
    },
    // 暂停(暂停时调用)(用户操作调用)
    onPlayerPause(player) {
      // console.log("暂停", player);
      this.$emit("onPlayerPause", player);
    },
    // 播放状态改变回调
    playerStateChanged(playerCurrentState) {
      // console.log("数据变化", playerCurrentState);
      //   this.player.pause();
      this.$emit("playerStateChanged", playerCurrentState);
    },
    // 准备就绪(预加载前会调用)(初始化调用)将侦听器绑定到组件的就绪状态。与事件监听器的不同之处在于，如果ready事件已经发生，它将立即触发该函数
    playerReadied(player) {
      // console.log("准备就绪", player);
      this.$emit("playerReadied", player);
    },
    // 结束(视频播放完毕调用)
    onPlayerEnded(player) {
      // console.log("结束", player);
      this.$emit("onPlayerEnded", player);
    },
    // 等待(视频中出现loading就会调用,加载时调用)(高频调用)
    onPlayerWaiting(player) {
      // console.log("等待", player);
      this.$emit("onPlayerWaiting", player);
    },
    // 播放中(进入播放状态会调用)(等待onPlayerWaiting和播放onPlayerPlay执行后会调用)(高频调用)
    onPlayerPlaying(player) {
      // console.log("播放中", player);
      this.$emit("onPlayerPlaying", player);
    },
    // 当播放器在当前播放位置下载数据时触发
    onPlayerLoadeddata(player) {
      // console.log("预加载", player);
      this.$emit("onPlayerLoadeddata", player);
    },
    // 进度更新(当前播放位置发生变化时触发)(视频接收到新内容会一直调用)(高频调用)
    onPlayerTimeupdate(player) {
      // console.log("进度更新", player);
      this.$emit("onPlayerTimeupdate", player);
    },
    // 媒体的readyState为HAVE_FUTURE_DATA或更高(预加载onPlayerLoadeddata调用后会调用)(初始化调用)
    onPlayerCanplay(player) {
      // console.log("是否播放", player);
      this.$emit("onPlayerCanplay", player);
    },
    // 能够从头到尾播放(是否播放onPlayerCanplay调用后会调用)(初始化调用)这意味着可以在不缓冲的情况下播放整个媒体文件
    onPlayerCanplaythrough(player) {
      // console.log("能够从头到尾播放", player);
      this.$emit("onPlayerCanplaythrough", player);
    },
  },
};
</script>
